<template>
  <section ref="frame" class="panel proteome-figure" :data-chart-id="chartId" :data-species-id="speciesId" :data-status="loading?'loading':error?'failed':figure?.status||'unavailable'" data-testid="proteome-figure">
    <div class="section-header"><div><h3>{{ title || figure?.title || chartId }}</h3><p v-if="figure" class="muted">{{ scopeLabel }} · {{ figure.coverage?.n_source?.toLocaleString() }} {{ cohortMode?'species':'sequence records' }}<span v-if="figure.coverage?.n_valid!==figure.coverage?.n_source"> · {{ figure.coverage?.n_valid?.toLocaleString() }} jointly valid</span></p></div><span v-if="figure" class="badge">{{ figure.status }}</span></div>
    <ModuleState v-if="loading" state="loading" title="Preparing visualization" message="Reading the complete-population result." />
    <ModuleState v-else-if="error" state="error" title="Visualization unavailable" :message="error" />
    <ModuleState v-else-if="!figure||figure.status==='unavailable'||figure.status==='failed'" state="missing" title="Result unavailable for this dataset" :message="reason" />
    <template v-else>
      <p v-if="figure.reason_code" class="muted">{{ reason }}</p>
      <div class="proteome-plot-scroll"><div :style="{minWidth: minimumWidth+'px'}"><EChart :option="option" :height="height" :auto-loading="false" :show-data-exports="false" :export-name="exportName" @chart-click="click" /></div></div>
      <p class="proteome-scientific-caption">{{ caption }}</p>
      <p v-if="figure.data?.correlation" class="muted">Spearman ρ={{ number(figure.data.correlation.rho) }} · paired n={{ figure.data.correlation.n.toLocaleString() }}<span v-if="figure.data.correlation.reason"> · {{ figure.data.correlation.reason }}</span></p>
      <p v-if="figure.data?.selenium_positive_n!==undefined" class="muted">Selenium-positive records: <strong>{{ figure.data.selenium_positive_n.toLocaleString() }}</strong><span v-if="figure.data.selenium_positive_n===0"> · no selenium-positive candidates</span></p>
      <div v-if="figure.data?.selenium_candidates?.length" class="table-wrap"><table><caption>Selenium-positive candidates · first {{ figure.data.selenium_candidates.length }} of {{ figure.data.selenium_positive_n }}</caption><thead><tr><th>Protein ID</th><th>Se atoms</th></tr></thead><tbody><tr v-for="r in figure.data.selenium_candidates" :key="r.protein_id"><td><button class="proteome-entity-link" data-testid="selenium-candidate" @click="protein(r)">{{ r.protein_id }}</button></td><td>{{ r.atoms.toLocaleString() }}</td></tr></tbody></table></div>
      <div v-if="chartId==='B05'" class="table-wrap"><table><thead><tr><th>Element</th><th>Total known atoms</th><th>Known-atom share (%)</th><th>Valid records</th></tr></thead><tbody><tr v-for="b in figure.data.budget" :key="b.element"><td>{{ b.element }}</td><td>{{ b.atoms===null?'NA':b.atoms.toLocaleString('en',{maximumFractionDigits:0}) }}</td><td>{{ b.share===null?'NA':number(100*b.share,5) }}</td><td>{{ b.n_valid??figure.coverage.n_source }}</td></tr></tbody></table></div>
      <div v-if="figure.data?.quadrants" class="table-wrap"><table><thead><tr><th>Quadrant</th><th>Records</th><th>Paired population (%)</th></tr></thead><tbody><tr v-for="q in figure.data.quadrants" :key="q.name"><td>{{ q.name }}</td><td>{{ q.n.toLocaleString() }}</td><td>{{ number(100*q.n/(figure.coverage.n_valid||1)) }}</td></tr></tbody></table></div>
      <div v-if="chartId==='D07'&&figure.data?.profiles" class="table-wrap"><table><thead><tr><th>Structure descriptor</th><th>Original median</th><th>Valid records</th><th>Missing</th></tr></thead><tbody><tr v-for="p in figure.data.profiles" :key="p.field"><td>{{ p.field }}</td><td>{{ number(p.quantiles?.[3]) }}</td><td>{{ p.n_valid }}</td><td>{{ p.n_missing }}</td></tr></tbody></table></div>
      <div v-if="!cohortMode" class="proteome-downloads"><a class="ghost-link" :href="download('chart')">Aggregate CSV</a><a class="ghost-link" :href="download('raw')">All record values</a><a class="ghost-link" :href="download('method')">Methods &amp; provenance</a><template v-if="figure.data?.kind==='ordination'"><a class="ghost-link" :href="download('pca')">All PCA coordinates</a><a class="ghost-link" :href="download('loadings')">All coefficients &amp; directions</a></template><a v-if="chartId==='D07'" class="ghost-link" :href="download('structure')">Complete sorted atlas</a><template v-if="['D14','D15'].includes(chartId)"><a class="ghost-link" :href="download('candidates')">All native scores</a><a class="ghost-link" :href="download('partial_candidates')">Partial evidence</a></template></div>
      <details class="proteome-method"><summary>Method, coverage and input fields</summary><p>{{ figure.method?.name }} · {{ figure.method_version }} · {{ figure.release_id }}</p><p v-if="figure.fields?.length">{{ figure.fields.map(f=>`${f.key} (${f.unit})`).join(' · ') }}</p><p>All valid records contribute before aggregation. Distribution intervals describe sequence records and are not confidence intervals.</p><div v-if="figure.data?.sensitivity?.length" class="table-wrap"><p>Pseudocount sensitivity uses deterministic diagnostic records only. The main PCA uses every valid record.</p><table><thead><tr><th>Pseudocount</th><th>Diagnostic records</th><th>Distance correlation with 0.5</th></tr></thead><tbody><tr v-for="r in figure.data.sensitivity" :key="r.pseudocount"><td>{{ r.pseudocount }}</td><td>{{ r.diagnostic_n }}</td><td>{{ number(r.distance_correlation,6) }}</td></tr></tbody></table></div><p class="proteome-version">Source {{ figure.source_hash }} · artifact {{ figure.artifact_version }}</p></details>
    </template>
  </section>
</template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import EChart from '../EChart.vue'
import ModuleState from '../ModuleState.vue'
import {figureOption,figureHeight,responsiveLayout} from '../../utils/proteomeCharts'
import {proteomeExportUrl} from '../../api/proteomeVisuals'
import {number} from '../../utils/proteomeFormat'
const props=defineProps({figure:Object,chartId:String,speciesId:String,scope:String,loading:Boolean,error:String,title:String,optionOverride:Object})
const emit=defineEmits(['bin','structure-window','species']);const frame=ref(null),narrow=ref(false),plotWidth=ref(1100);let observer
onMounted(()=>{observer=new ResizeObserver(([entry])=>{narrow.value=entry.contentRect.width<700;plotWidth.value=entry.contentRect.width});if(frame.value)observer.observe(frame.value)})
onBeforeUnmount(()=>observer?.disconnect())
const minimumWidth=computed(()=>props.chartId==='D12'?Math.max(700,(props.figure?.coverage?.n_valid||0)*14+600):['D07','D13','D15'].includes(props.chartId)?700:0)
const cohortMode=computed(()=>['D11','D12','D16'].includes(props.chartId))
const option=computed(()=>props.optionOverride?responsiveLayout(props.optionOverride,props.chartId,narrow.value):figureOption({...props.figure,__narrow:narrow.value,__width:plotWidth.value}))
const height=computed(()=>props.chartId==='D12'?Math.max(760,(props.figure?.coverage?.n_valid||0)*20+230):narrow.value?({B01:820,B02:1620,D01:880,D02:850,B10:850,B15:850,D03:1050,D06:850,D14:850,D11:900}[props.chartId]||figureHeight(props.chartId)):figureHeight(props.chartId))
const scopeLabel=computed(()=>props.figure?.primary_scope==='full'?'Full population':'Core population with available supplemental fields')
const reason=computed(()=>({missing_required_fields:'Some required fields are not available in this dataset.',insufficient_n:'Too few complete records for this analysis.',rank_one:'The input has one independent direction; a one-dimensional result is shown.',rank_lt_two:'A two-dimensional density is not defined; complete aggregate data are retained.',constant_matrix:'The input descriptors are constant.',grid_convergence_tolerance:'The density grid did not meet the requested numerical tolerance.'}[props.figure?.reason_code]||props.figure?.reason_code||'Required measurements are not available. Other modules remain usable.'))
const captions={B01:'Each descriptor has its own units and axis. Circle: median; diamond: mean; thick band: IQR; thin line: P05–P95.',B02:'All 52 Core numeric descriptors. Colors describe within-field quantiles, not cross-species importance. Constant and missing values remain explicit.',B03:'All positive lengths are included, including the extreme tails. The lower panel is the complete-record ECDF.',B04:'Sequence quality and annotation completeness use separate criteria. Missing QC evidence is unavailable, not low quality.',B05:'Upper panels weight protein records equally. The lower budget sums atoms across all records; it does not measure expression or cellular resource consumption.',B07:'ECDFs use actual length-quantile groups; ties may produce unequal group sizes. pI=7 is a reference.',B08:'Equal maximum violin width; actual group n is reported separately. True GRAVY=0 remains included.',B09:'Twenty standard amino acids in fixed order. Other residues are not discarded and reclosed to 100%.',B11:'Helix, turn and sheet propensities can overlap; they are not a partition of 100%.',B12:'ZC is a sequence chemical descriptor, not a measured cellular redox state.',D01:'Complete-case, robust-scaled, mean-centered PCA. Hexagon colors encode all valid records; arrows are feature–PC correlations.',D02:'All valid N/aa–S/aa pairs. Line: conditional median; band and side intervals: P10–P90. Spearman uses average ranks.',D03:'Twenty standard AA counts, pseudocount 0.5, CLR and mean-centered PCA. Nonstandard-only records do not become artificial uniform compositions.',D04:'Biochemical classes may overlap. Each class is shown as its own complete-record percentage distribution.',D05:'Each feature is robust centered; the median is zero by construction. Bands connect feature quantiles, not individual protein trajectories.',D06:'Quadrants use GRAVY <0 / ≥0 and instability <40 / ≥40. They do not establish membrane localization or experimental stability.',D07:'Overview blocks cover every sorted row once. Values are per-block medians of robust z, not individual protein measurements. Open any precise rank window below.',D08:'Accessibility distributions use actual flexibility groups and all valid members; the association is descriptive.',D09:'Each descriptor has its own robust scale. Optical proxies are not mass-spectrometry detectability measurements.',D10:'Contours enclose 50%, 80% and 95% of estimated KDE probability mass, not confidence intervals. Marginal counts retain all valid records.',D13:'Pairwise-complete Spearman correlations with average ranks. Missing or constant pairs are undefined, not zero; no significance stars.',D14:'Module-native scores retain their own definitions and cannot be compared as a common score. Main ranking requires complete components; partial evidence is separate.',D15:'Union of module Top 3 candidates, deduplicated. Percentiles are within-module ranks, not probabilities and not additive.'}
const caption=computed(()=>props.chartId==='D07'&&props.figure?.data?.rows?`Individual records at sorted ranks ${props.figure.data.rank_start+1}–${props.figure.data.rank_start+props.figure.data.rows.length}. This window shows ${props.figure.data.rows.length} of ${props.figure.data.n_source.toLocaleString()} source records; the complete atlas remains available.`:props.figure?.data?.fallback==='entropy_only'?'CLR-PCA is unavailable; the independent entropy distribution retains all finite entropy records. No artificial coordinates are generated.':props.figure?.data?.fallback==='resource_intervals'?'PCA is unavailable; original-unit resource intervals retain the available element descriptors.':captions[props.chartId]||'Full-population statistics; display aggregation preserves the complete valid-record count.')
const exportName=computed(()=>[props.speciesId,props.scope,props.chartId,props.figure?.artifact_version,props.figure?.variant_id?.slice(0,12),props.figure?.data?.rows&&props.chartId==='D07'?`r${props.figure.data.rank_start+1}-${props.figure.data.rank_start+props.figure.data.rows.length}`:''].filter(Boolean).join('_'))
function download(kind){return proteomeExportUrl(props.speciesId,{scope:props.scope,chart_id:props.chartId,kind,variant_id:props.figure?.variant_id||'',artifact_version:props.figure?.artifact_version||'',source_hash:props.figure?.source_hash||''})}
function protein(row){window.dispatchEvent(new CustomEvent('stoich-entity-chart-click',{detail:{...row,species_id:props.speciesId,entity_id:row.protein_id,report_entity_key:row.protein_id}}))}
function click(event){const raw=event?.data?.raw||{};if(raw.bin_id)emit('bin',{...raw,figure:props.figure});else if(raw.rank_start!==undefined)emit('structure-window',raw.rank_start);else if(raw.entity_type==='species')emit('species',raw.species_id)}
</script>
